-- Seed: denial-driving rules, round 2 — UnitedHealthcare Community Plan
-- Ohio and Anthem BCBS Ohio.
--
-- Round 1 left both payers with zero prior_auth_required rules. These are
-- the documents that close that, all four verified by SHA-256 against the
-- URL recorded below:
--
--   UHC Ohio 2026 Care Provider Manual              (887,476 bytes)
--   UHC Nonphysician E/M Codes Policy 2026R0112D    (259,590 bytes)
--   UHC Ohio Prior Authorization list, eff 11/1/25  (725,158 bytes)
--   Anthem Ohio PA quick guide, 1 March 2026        (captured from the
--     provider-news page, which renders its content with JavaScript —
--     the static HTML yields 13 characters)
--
-- WHY THESE ARE FEWER ROWS THAN FACTS
-- fetchPayerRule() ends in LIMIT 1, so two live rows on one
-- (payer, state, code, attribute) key make the answer depend on row
-- order. The extraction produced eight provider_taxonomy_allowed facts
-- for UHC Ohio over overlapping code sets; they are consolidated into one
-- row per code, with the other verbatim sentences carried in
-- value->'supportingQuotes'. Nothing was discarded to achieve this.
--
-- WHAT THE AUDITOR REJECTED
--   * an SBIRT bundling rule with the direction inverted — the screening
--     bundles into the E/M, not the reverse
--   * a prior-auth rule inferred from "services not on the ODM Fee
--     Schedule", where the document never says which codes those are
--   * two quotes stitched together across bullet lines rather than copied
--     contiguously; one was re-grounded from the source and kept, the
--     other dropped
--
-- THE MAPPING TRAP, AGAIN
-- Anthem's guide requires prior authorization for "Home healthcare
-- (physical, occupational, and speech therapy) and skilled nursing (after
-- 18 combined visits)". That is a home health AGENCY benefit. Mapping it
-- onto 99341-99350 would put a confident, wrong prior-auth flag on every
-- physician home visit. It is recorded as an explicit scope exclusion
-- instead. Likewise UHC's "Home health care" row (G0151-G0300).
--
-- 9 consolidated rules over 114 (payer, code, attribute) keys.
-- Every primary and supporting quote re-verified verbatim at build time.
--
-- Idempotent: deterministic UUIDs + ON CONFLICT (id) DO UPDATE.

BEGIN;

INSERT INTO source_document (id, payer_id, url, document_type, title, retrieved_at, content_hash, cms_license_token_used, source_metadata, extracted_at)
VALUES
  ('c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a01'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'https://www.uhcprovider.com/content/dam/provider/docs/public/admin-guides/comm-plan/OH-Care-Provider-Manual.pdf', 'provider_manual', 'UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)', now(), 'sha256:3591a7e0f0400c51b9215cd5a0f8a02e128a11e8076e5714db6293f6296695ab', FALSE, '{}'::jsonb, now()),
  ('c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a02'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'https://www.uhcprovider.com/content/dam/provider/docs/public/policies/medicaid-comm-plan-reimbursement/UHCCP-Nonphysician-Health-Care-Professional-Billing-Evaluation-Mgmt-Codes-Policy.pdf', 'reimbursement_policy', 'UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D', now(), 'sha256:edffe604be9d3c07ffa79ce17b43b464eb951718cb5d6afd36f4b70b0f33d6e9', FALSE, '{}'::jsonb, now()),
  ('c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a03'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'https://www.uhcprovider.com/content/dam/provider/docs/public/commplan/oh/prior-auth/OH-UHCCP-PA-Effective-11-1-2025.pdf', 'medical_policy', 'UnitedHealthcare Community Plan of Ohio — Prior Authorization Requirements, effective 11/1/2025', now(), 'sha256:55c13d6c9e95cd78ff4e9648691c5bafb6aa154513a30f70e843bf28b076f9c6', FALSE, '{}'::jsonb, now()),
  ('c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a04'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'https://providernews.anthem.com/ohio/articles/quick-guide-to-services-requiring-prior-authorization-28751', 'medical_policy', 'Anthem BCBS Ohio — Quick guide to services requiring prior authorization (Medicaid / MyCare, 1 March 2026)', now(), 'sha256:ca50e8421e4945ce05c65e0d52a72d770bac21773e70287f43507d3b8fff91ba', FALSE, '{}'::jsonb, now())
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, url = EXCLUDED.url, extracted_at = now();

