INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('5cff500a-fa41-499c-8773-fab6439ca975'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99341', 'provider_taxonomy_allowed', '{"answer":"Only a Physician (MD or DO) or one of the four qualified health care professionals CMS recognises for E/M — nurse practitioner (NP), clinical nurse specialist (CNS), certified nurse midwife (CNM) or physician assistant (PA) — may report this code. UnitedHealthcare Community Plan will NOT reimburse it when the billing party is a nonphysician health care professional reporting under its own individual or group TIN. The edit keys on the billing TIN, not only on the individual clinician''s licence. Specialties a home-based palliative practice is most likely to employ that are named on the barred list: Home Health Care Agency; Home Health Aide; Home Health/Private Duty Nurse; Home Health/Home Infusion/Home IV Therapy; Visiting Nurse; Waiver Nursing; Nurse, Registered; Nurse, Licensed Practical; Licensed Vocational Nurse; Master of Social Work; Social Worker (Registered Social Worker); Social Worker, Licensed Clinical/Medical; Psychiatric Social Work; Licensed Professional Counselor; Pastoral Counselor; Case Management; Nutritionist (Registered Dietician); Lactation Specialist; Psychology, Clinical (Doctor of Psychology). Ohio''s state exception lets pharmacists bill only E/M 99202, 99203, 99211-99215 (plus 90460, 90471-90474, 96372) — no home-visit, ACP, prolonged, TCM, CCM/PCM or unlisted E/M code is in that list, so the exception does not reach this code. Do not import Washington''s exception, which does list 99347-99350 and 99417 for pharmacists; that is a different state. Separately, Ohio Medicaid must have screened, enrolled and credentialed the provider before any service is rendered, N.P.s and P.A.s bill under their own tax ID and NPI per their collaborative agreement, and a P.A. may not be enrolled as a solo provider. TELEHEALTH — DO NOT CONFLATE THE TWO LISTS: UnitedHealthcare''s Telehealth/Virtual Health Policy names the CMS-designated practitioners eligible to be reimbursed for telehealth services, and that list does include registered dietitians, clinical psychologists and clinical social workers. It is a list of who may deliver a telehealth service, NOT a list of who may report an E/M code. A clinical social worker, dietitian or psychologist on that telehealth list still may not report this code; delivering the visit by audio-video changes the modifier, not the eligible biller.","appliesToService":"Evaluation and Management (E/M) services — the policy defines these as CPT 98000-98016, 99091 and 99202-99499, which contains every code listed here","mappedFrom":"service-level rule mapped to this code","sourceDocument":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D","supportingQuotes":[{"label":"who may report E/M","quote":"CPT guidance instructs that E/M (CPT codes 98000-98016, 99091, 99202-99499) should only be reported by Physicians or other qualified health care professionals. In accordance with CMS guidelines, the only qualified health care professionals that may report E/M services are nurse practitioners (NP), clinical nurse specialists (CNS), certified nurse midwives (CNM) and Physician assistants (PA), none of which are considered nonphysician health care professionals for purposes of this policy.","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"barred-specialty list heading","quote":"Nonphysician Health Care Professionals for Medicaid Products Not Allowed to Report E&M Services","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"definition of Physician","quote":"Physician A Doctor of Medicine (MD) or Doctor of Osteopathy (DO)","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"Ohio pharmacist exception (closed list)","quote":"In addition, Ohio Medicaid allows Pharmacists to bill E/M CPT 99202, 99203, 99211, 99212, 99213, 99214, 99215, 90460, 90471, 90472, 90473, 90474 and 96372","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"N.P./P.A. billing identity","quote":"Use their tax ID and NPI, and we will process the claims according to their agreement.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"P.A.s may not enrol as solo providers","quote":"N.P.s may enroll with the state as solo care providers, but P.A.s cannot. P.A.s must be part of a group practice.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"ODM screening, enrolment and credentialing prerequisite","quote":"Please note, you are not able to render services to Medicaid members until you are fully screened, enrolled and credentialed (if required) by Ohio Medicaid.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"telehealth practitioner list — eligibility to deliver telehealth, not to report E/M","quote":"UnitedHealthcare Community Plan recognizes the CMS-designated practitioners eligible to be reimbursed for Telehealth services: Examples of practitioners are listed below: Physician Nurse practitioner Physician assistant Nurse-midwife Clinical nurse specialist Registered dietitian or nutrition professional Clinical psychologist Clinical social worker Certified Registered Nurse Anesthetists","document":"UnitedHealthcare Community Plan — Telehealth/Virtual Health Policy"}]}'::jsonb, 'varies', 0.92, DATE '2026-01-01', NULL, 'c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a02'::uuid, 'UnitedHealthcare Community Plan will not reimburse E/M services (CPT codes 98000-98016, 99091, 99202-99499) when reported by nonphysician health care professionals reporting under their own individual or group tax identification number (TIN). For purposes of this policy, the specialties that are considered nonphysician health care professionals are listed below.', 'extract:denial-rules-round2-2026-08'),
  ('647d7811-cdac-48e8-820b-c39612e8af1d'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid, 'OH', 'medicaid_mco', '99342', 'provider_taxonomy_allowed', '{"answer":"Only a Physician (MD or DO) or one of the four qualified health care professionals CMS recognises for E/M — nurse practitioner (NP), clinical nurse specialist (CNS), certified nurse midwife (CNM) or physician assistant (PA) — may report this code. UnitedHealthcare Community Plan will NOT reimburse it when the billing party is a nonphysician health care professional reporting under its own individual or group TIN. The edit keys on the billing TIN, not only on the individual clinician''s licence. Specialties a home-based palliative practice is most likely to employ that are named on the barred list: Home Health Care Agency; Home Health Aide; Home Health/Private Duty Nurse; Home Health/Home Infusion/Home IV Therapy; Visiting Nurse; Waiver Nursing; Nurse, Registered; Nurse, Licensed Practical; Licensed Vocational Nurse; Master of Social Work; Social Worker (Registered Social Worker); Social Worker, Licensed Clinical/Medical; Psychiatric Social Work; Licensed Professional Counselor; Pastoral Counselor; Case Management; Nutritionist (Registered Dietician); Lactation Specialist; Psychology, Clinical (Doctor of Psychology). Ohio''s state exception lets pharmacists bill only E/M 99202, 99203, 99211-99215 (plus 90460, 90471-90474, 96372) — no home-visit, ACP, prolonged, TCM, CCM/PCM or unlisted E/M code is in that list, so the exception does not reach this code. Do not import Washington''s exception, which does list 99347-99350 and 99417 for pharmacists; that is a different state. Separately, Ohio Medicaid must have screened, enrolled and credentialed the provider before any service is rendered, N.P.s and P.A.s bill under their own tax ID and NPI per their collaborative agreement, and a P.A. may not be enrolled as a solo provider. TELEHEALTH — DO NOT CONFLATE THE TWO LISTS: UnitedHealthcare''s Telehealth/Virtual Health Policy names the CMS-designated practitioners eligible to be reimbursed for telehealth services, and that list does include registered dietitians, clinical psychologists and clinical social workers. It is a list of who may deliver a telehealth service, NOT a list of who may report an E/M code. A clinical social worker, dietitian or psychologist on that telehealth list still may not report this code; delivering the visit by audio-video changes the modifier, not the eligible biller.","appliesToService":"Evaluation and Management (E/M) services — the policy defines these as CPT 98000-98016, 99091 and 99202-99499, which contains every code listed here","mappedFrom":"service-level rule mapped to this code","sourceDocument":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D","supportingQuotes":[{"label":"who may report E/M","quote":"CPT guidance instructs that E/M (CPT codes 98000-98016, 99091, 99202-99499) should only be reported by Physicians or other qualified health care professionals. In accordance with CMS guidelines, the only qualified health care professionals that may report E/M services are nurse practitioners (NP), clinical nurse specialists (CNS), certified nurse midwives (CNM) and Physician assistants (PA), none of which are considered nonphysician health care professionals for purposes of this policy.","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"barred-specialty list heading","quote":"Nonphysician Health Care Professionals for Medicaid Products Not Allowed to Report E&M Services","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"definition of Physician","quote":"Physician A Doctor of Medicine (MD) or Doctor of Osteopathy (DO)","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"Ohio pharmacist exception (closed list)","quote":"In addition, Ohio Medicaid allows Pharmacists to bill E/M CPT 99202, 99203, 99211, 99212, 99213, 99214, 99215, 90460, 90471, 90472, 90473, 90474 and 96372","document":"UnitedHealthcare Community Plan — Nonphysician Health Care Professionals Billing E/M Codes Policy 2026R0112D"},{"label":"N.P./P.A. billing identity","quote":"Use their tax ID and NPI, and we will process the claims according to their agreement.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"P.A.s may not enrol as solo providers","quote":"N.P.s may enroll with the state as solo care providers, but P.A.s cannot. P.A.s must be part of a group practice.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"ODM screening, enrolment and credentialing prerequisite","quote":"Please note, you are not able to render services to Medicaid members until you are fully screened, enrolled and credentialed (if required) by Ohio Medicaid.","document":"UnitedHealthcare Community Plan Ohio — 2026 Care Provider Manual (PMG 20251008-164146)"},{"label":"telehealth practitioner list — eligibility to deliver telehealth, not to report E/M","quote":"UnitedHealthcare Community Plan recognizes the CMS-designated practitioners eligible to be reimbursed for Telehealth services: Examples of practitioners are listed below: Physician Nurse practitioner Physician assistant Nurse-midwife Clinical nurse specialist Registered dietitian or nutrition professional Clinical psychologist Clinical social worker Certified Registered Nurse Anesthetists","document":"UnitedHealthcare Community Plan — Telehealth/Virtual Health Policy"}]}'::jsonb, 'varies', 0.92, DATE '2026-01-01', NULL, 'c1a1d3f2-6b74-4b8e-9a21-7c5e2f4d8a02'::uuid, 'UnitedHealthcare Community Plan will not reimburse E/M services (CPT codes 98000-98016, 99091, 99202-99499) when reported by nonphysician health care professionals reporting under their own individual or group tax identification number (TIN). For purposes of this policy, the specialties that are considered nonphysician health care professionals are listed below.', 'extract:denial-rules-round2-2026-08'),
